#if MIXER_F11_ANDROID_FIXTURE || MIXER_F11_HOST_ACTION_FIXTURE
import Foundation
import MixerUI

@_spi(PrivateFieldLogEditor)
public enum F11AndroidAction: String, Sendable {
    case save = "entry.saveDraft"
    case commit = "entry.commit"

    public var workspaceRevision: UInt64 { self == .save ? 1 : 2 }
}

struct F11AndroidAuthority {
    struct Frame: Equatable {
        let owner: UInt64
        let attachment: UInt64
        let input: UInt64
        let probe: UInt64
        let generation: UInt64
        let serial: UInt64
        let revision: UInt64
    }

    static let field = "entry.f1100000-0000-4000-8000-000000000001.note"
    static let original = "Café e\u{0301} 👩🏽‍🔬\n東京\n\nLast line\n"
    static let edited = original + "Edited"
    private var installed: Frame?
    private var drawn = false
    private var next: F11AndroidAction? = .save

    mutating func install(_ frame: Frame) {
        installed = frame
        drawn = false
    }

    mutating func retire() {
        installed = nil
        drawn = false
        next = nil
    }

    mutating func acknowledge(_ frame: Frame) -> Bool {
        guard installed == frame, !drawn else { return false }
        drawn = true
        return true
    }

    func isCurrent(_ frame: Frame) -> Bool { drawn && installed == frame }

    mutating func consume(_ frame: Frame, snapshot: UIRenderSnapshot, event: UIEventEnvelope,
                          submit: (F11AndroidAction, String) -> Bool) -> Bool {
        guard isCurrent(frame), frame.revision == 2, snapshot.document.revision == frame.revision,
              event.revision == frame.revision, event.event == .activate,
              let route = try? snapshot.route(event), route.nodeID == route.actionID,
              let action = F11AndroidAction(rawValue: route.actionID), action == next,
              let note = snapshot.document.root.children.first, note.id == Self.field,
              let value = note.properties["value"]?.string, value.utf8.elementsEqual(Self.edited.utf8),
              submit(action, value) else { return false }
        next = action == .save ? .commit : nil
        return true
    }

    static func nativeDocument(_ guest: UIDocument) -> UIDocument {
        guard guest.revision == 2 else { return guest }
        let controls = [(F11AndroidAction.save, "Save draft"), (.commit, "Commit entry")].map { action, label in
            UINode(id: action.rawValue, kind: .button, properties: ["label": .string(label)],
                   actions: [.init(id: action.rawValue, event: .activate)])
        }
        return UIDocument(revision: guest.revision, root: UINode(id: guest.root.id, kind: guest.root.kind,
            children: guest.root.children + controls))
    }
}
#endif

