#if os(Android) && MIXER_F11_ANDROID_FIXTURE
import FieldLogFeatures
import FieldLogModels
import FieldLogStorage
import Foundation
@_spi(AndroidGuestUIV1) @_spi(PrivateFieldLogEditor) import MixerCapabilityActivation
@_spi(InstalledApplicationStorage) import MixerCapabilities
import MixerUpdates

private enum F11Refusal: Error { case asset, workspace, activation }

private func read(_ directory: URL, _ name: String, maximum: Int = 65_536) throws -> Data {
    let file = try FileHandle(forReadingFrom: directory.appendingPathComponent(name))
    defer { try? file.close() }
    guard let bytes = try file.read(upToCount: maximum + 1), (1...maximum).contains(bytes.count) else {
        throw F11Refusal.asset
    }
    return bytes
}

private final class F11Owner: @unchecked Sendable {
    static let shared = F11Owner()
    private let lock = NSLock()
    private var task: Task<Void, Never>?
    private var transaction: Task<Void, Never>?
    private var next: F11AndroidAction? = .save
    private var status = "Idle"
    private var closing = false

    var message: String { lock.withLock { status } }

    func start(root: String, packet: String, installation: String, bundle: String) -> Bool {
        guard installation == "fieldlog-f11-android", bundle == "dev.mixer.fieldlog.f11private",
              root.hasPrefix("/"), packet == root + "/offer" else { return false }
        return lock.withLock {
            guard task == nil, !closing else { return false }
            next = .save
            status = "Opening"
            task = Task { await self.run(root: URL(fileURLWithPath: root), packet: URL(fileURLWithPath: packet),
                                         installation: installation) }
            return true
        }
    }

    func close() -> Bool {
        lock.withLock {
            closing = true
            if let task { task.cancel() }
            else if status != "Retirement unconfirmed" { status = "Closed"; closing = false }
            return true
        }
    }

    private func submit(_ action: F11AndroidAction, value: String, repository: WorkspaceRepository) -> Bool {
        lock.withLock {
            guard !closing, task != nil, transaction == nil, next == action else { return false }
            next = nil
            transaction = Task {
                do {
                    let result = try await F11Pair25.transact(action, value: value, repository: repository)
                    self.lock.withLock {
                        self.next = action == .save ? .commit : nil
                        self.status = "Healthy action=\(action.rawValue) workspaceRevision=\(result.revision)"
                        self.transaction = nil
                    }
                } catch {
                    self.lock.withLock {
                        self.status = "Failed F11 transaction: \(error)"
                        self.transaction = nil
                    }
                }
            }
            return true
        }
    }

    private func run(root: URL, packet: URL, installation: String) async {
        var runtime: CapabilityGuestUIAndroidRuntime?
        var repository: WorkspaceRepository?
        var terminal = "Closed"
        do {
            let material = root.appendingPathComponent("installed")
            let workspace = root.appendingPathComponent("workspace")
            guard ReleaseVerifier.sha256(try read(workspace, "workspace.json")) == F11Pair25.seedHash else {
                throw F11Refusal.workspace
            }
            let repo = try WorkspaceRepository(directory: workspace)
            repository = repo
            let materials: [CapabilityMaterialFile] = [
                .init(role: .bridgePolicy, bytes: try read(material, "bridge.json")),
                .init(role: .configuration(capabilityID: CapabilitySchemas.storageID), bytes: try read(material, "storage.json")),
                .init(role: .installedGrant(capabilityID: CapabilitySchemas.storageID), bytes: try read(material, "storage-grant.json")),
            ]
            let execution = try InstalledCapabilityExecution(privateDevelopmentFieldLogNoteFixtureJSON: read(material, "identity.json"),
                materials: materials, trustRootsJSON: read(material, "roots.json"), privateContainer: root,
                repository: F11Pair25(repo))
            let config = CapabilityColdStartConfiguration(directory: root.appendingPathComponent("recovery"),
                channel: "beta", installation: installation, observationSeconds: 1)
            try Task.checkCancellation()
            let owner = try await CapabilityGuestUIAndroidRuntime.openPrivateF11(configuration: config, execution: execution) {
                self.submit($0, value: $1, repository: repo)
            }
            runtime = owner
            let wasm = try read(packet, "payload.wasm", maximum: 2442)
            guard wasm.count == 2442,
                  ReleaseVerifier.sha256(wasm) == "b3def2b5d11c0a350d33a44ff0cd55f4a7e97f6979e547c49ab13bde696d4fe5" else {
                throw F11Refusal.asset
            }
            try await owner.stage(manifest: read(packet, "signed-manifest.json"),
                                  assignment: read(packet, "assignment.json"), bytes: wasm)
            let initial = try await owner.start()
            guard initial.firstUIProtocolFailure == nil else { throw F11Refusal.activation }
            var healthy = false
            while !Task.isCancelled {
                let state = owner.recoverySnapshot()
                switch state.activation.phase {
                case .healthyGuest where !healthy:
                    healthy = true
                    lock.withLock { if status == "Opening" { status = "Healthy revision=1" } }
                case .healthyGuest, .provisionalGuest: break
                default: throw F11Refusal.activation
                }
                try await Task.sleep(for: .milliseconds(100))
            }
        } catch is CancellationError {
            terminal = "Closed"
        } catch {
            terminal = "Failed F11: \(error)"
        }
        let accepted = lock.withLock { closing = true; return transaction }
        await accepted?.value
        if let runtime, !(await Task.detached { await runtime.close() }.value) {
            terminal = "Retirement unconfirmed"
        }
        await repository?.close()
        lock.withLock { task = nil; status = terminal; closing = false }
    }
}

@_cdecl("f11_signed_submit")
func f11Submit(_ action: Int32, _ context: Int64, _ root: UnsafePointer<CChar>, _ packet: UnsafePointer<CChar>,
               _ installation: UnsafePointer<CChar>, _ bundle: UnsafePointer<CChar>) -> Int32 {
    guard context == 0 else { return 0 }
    switch action {
    case 1:
        guard let root = String(validatingCString: root), let packet = String(validatingCString: packet),
              let installation = String(validatingCString: installation),
              let bundle = String(validatingCString: bundle) else { return 0 }
        return F11Owner.shared.start(root: root, packet: packet, installation: installation, bundle: bundle) ? 1 : 0
    case 2: return F11Owner.shared.close() ? 1 : 0
    default: return 0
    }
}

@_cdecl("f11_signed_status")
func f11Status(_ output: UnsafeMutablePointer<CChar>, _ capacity: Int) {
    guard capacity > 0 else { return }
    let bytes = F11Owner.shared.message.utf8.prefix(capacity - 1)
    for (index, byte) in bytes.enumerated() { output[index] = CChar(bitPattern: byte) }
    output[bytes.count] = 0
}
#endif

