int32_t f11_signed_draw(uint64_t facade, uint64_t attachment, uint64_t token, uint32_t display) {
    return display == 1 ? mxis_guest_ui_witness(facade, attachment, token, MXIS_WITNESS_DRAWN) : MXUIT_INVALID;
}

extern int32_t mxis_f11_note_event(uint64_t, uint64_t, uint64_t, const uint8_t *, intptr_t);

JNIEXPORT jint JNICALL Java_dev_mixer_android_F11NativeIngress_event(JNIEnv *env, jobject owner,
        jlong facade, jlong attachment, jlong input, jbyteArray original) {
    if (!main_looper(env) || !owns_registration(env, owner) || !original
        || facade <= 0 || attachment <= 0 || input <= 0) return MXUIT_INVALID;
    const jsize count = (*env)->GetArrayLength(env, original);
    if (count < 1 || count > 4096) return MXUIT_INVALID;
    jbyte bytes[4096];
    (*env)->GetByteArrayRegion(env, original, 0, count, bytes);
    if ((*env)->ExceptionCheck(env)) return MXUIT_INVALID;
    return mxis_f11_note_event((uint64_t)facade, (uint64_t)attachment, (uint64_t)input,
                              (const uint8_t *)bytes, count);
}

