import MixerUpdates

actor F11Pair25: InstalledApplicationStorageServing {
    static let draftID = UUID(uuidString: "F1100000-0000-4000-8000-000000000001")!
    static let projectID = UUID(uuidString: "F1100000-0000-4000-8000-000000000003")!
    static let workspaceID = UUID(uuidString: "F1100000-0000-4000-8000-000000000004")!
    static let seedHash = "334f3dbcf08b6b1e363da63fad7388fcf7496c9573c3ac0315fd4e0c87a3876d"
    static let original = "Café e\u{0301} 👩🏽‍🔬\n東京\n\nLast line\n"
    static let edited = original + "Edited"
    let repository: WorkspaceRepository

    init(_ repository: WorkspaceRepository) { self.repository = repository }

    func get(_ request: KVGetArguments) async throws -> KVGetResponse {
        let workspace = await repository.snapshot()
        guard request.namespace == "fieldlog-d8-f11-note", request.key == "note", workspace.revision == 1,
              let draft = try? Self.boundDraft(workspace, note: Self.original) else {
            throw CapabilityFailure.unavailable
        }
        return .init(found: true, valueBase64: Data(draft.note.utf8).base64EncodedString())
    }

    func put(_ request: KVPutArguments, maximumTotalBytes: Int, maximumEntries: Int) async throws -> KVMutationResponse {
        throw CapabilityFailure.permissionDenied
    }

    func delete(_ request: KVDeleteArguments) async throws -> KVMutationResponse {
        throw CapabilityFailure.permissionDenied
    }

    static func transact(_ action: F11AndroidAction, value: String, repository: WorkspaceRepository) async throws -> Workspace {
        guard value.utf8.elementsEqual(edited.utf8) else { throw FieldLogError.missingRecord }
        return try await repository.transact(expectedRevision: action.workspaceRevision) { workspace in
            let kind: EntrySaveIntent.Kind = action == .save ? .draft : .commit
            var draft = try boundDraft(workspace, note: action == .save ? original : edited)
            draft.note = value
            if kind == .draft { draft.updatedAt = Date() }
            try EntrySaveIntent(projectID: projectID, draft: draft, kind: kind).apply(to: &workspace)
        }
    }

    private static func boundDraft(_ workspace: Workspace, note: String) throws -> EntryDraft {
        guard workspace.id == workspaceID, workspace.restoration.selectedProjectID == projectID,
              workspace.restoration.openDraftID == draftID,
              !workspace.entries.contains(where: { $0.id == draftID }),
              let draft = workspace.drafts.first(where: { $0.id == draftID }),
              draft.projectID == projectID, draft.note.utf8.elementsEqual(note.utf8) else {
            throw FieldLogError.missingRecord
        }
        return draft
    }
}
#endif

