package dev.mixer.android;

import android.app.Activity;
import android.view.inputmethod.EditorInfo;
import android.widget.EditText;
import android.widget.FrameLayout;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

public final class F11RendererHost {
    private static final String NOTE = "entry.f1100000-0000-4000-8000-000000000001.note";

    private static void require(boolean result, String reason) {
        if (!result) throw new AssertionError(reason);
    }

    public static void main(String[] args) throws Exception {
        Path frames = Path.of(args[0]);
        byte[] appearance = Files.readAllBytes(Path.of(args[1]));
        ConcreteHostProbe.reset();
        Activity activity = new Activity();
        activity.assets.put(InstalledAppearanceV2.DESCRIPTOR, appearance);
        FrameLayout root = new FrameLayout(activity);
        root.layout(0, 0, 1206, 2622);
        activity.window.getDecorView().layout(0, 0, 1206, 2622);
        root.hostAttach(new Object());
        List<byte[]> events = new ArrayList<>();
        NativeOwnerV2 owner = NativeOwnerV2.external(activity, root, new ExternalFrameSourceV2(events::add),
            AndroidUIProfile.MEASURED_MULTILINE_LONG_NOTES_V4);
        try {
            owner.installExternal(Files.readAllBytes(frames.resolve("v4-1.json")), appearance);
            require(owner.externalCurrent(), "Initial V4 installation");
            EditText note = (EditText) owner.externalView(NOTE);
            require(note.requestFocus(), "Note focus");
            var connection = note.onCreateInputConnection(new EditorInfo());
            require(connection != null, "Note input connection");
            require(connection.setSelection(note.getText().length(), note.getText().length()), "End selection");
            require(connection.commitText("Edited", 1), "Append Edited");
            require(events.size() == 1 && Arrays.equals(events.get(0), Files.readAllBytes(frames.resolve("exact-edit.json"))),
                "Native edit bytes differ from the signed host replay");
            owner.installExternal(Files.readAllBytes(frames.resolve("v4-2.json")), appearance);
            require(owner.externalCurrent(), "Edited V4 installation");
            require(owner.externalView("entry.saveDraft").performClick(), "Native Save click");
            require(owner.externalView("entry.commit").performClick(), "Native Commit click");
            require(events.size() == 3, "Unexpected count of original V4 packets");
            for (int index = 1; index <= 2; index++) {
                String action = index == 1 ? "entry.saveDraft" : "entry.commit";
                require(Arrays.equals(events.get(index), Files.readAllBytes(frames.resolve(action + ".json"))),
                    "Native action bytes differ for " + action);
            }
        } finally {
            owner.close();
        }
        require(owner.cleanupLedger().primary() == null, "Unexpected renderer cleanup error");
        System.out.println("V4 real renderer on controlled Android leaves: exact edit, Save and Commit packets, clean close");
    }
}

