package dev.mixer.android;

// Main-thread evidence for one window traversal. A callback alone carries no
// buffer-produced bit, so only readback of this traversal's marker can complete it.
final class FrameBufferEvidence {
    private final int marker;
    private boolean recorded;
    private boolean callback;
    private boolean retired;

    FrameBufferEvidence(int serial) {
        if (serial <= 0 || serial > 0x00ffffff) throw new IllegalArgumentException("frame serial");
        marker = 0xff000000 | (0x004d829b ^ serial);
    }

    int marker() { return marker; }
    int complement() { return marker ^ 0x00ffffff; }

    boolean record(boolean hardwareCanvas) {
        if (retired || recorded || !hardwareCanvas) return false;
        recorded = true;
        return true;
    }

    boolean committed() {
        if (retired || !recorded || callback) return false;
        callback = true;
        return true;
    }

    boolean matches(boolean copied, int first, int second) {
        return !retired && callback && copied && first == marker && second == complement();
    }

    void retire() { retired = true; }
}

