package dev.mixer.android;

import java.nio.file.Files;
import java.nio.file.Path;
import java.text.Normalizer;
import java.util.Arrays;

final class OriginalPackets {
    private static final String FIELD = "entry.f1100000-0000-4000-8000-000000000001.note";
    private static final AndroidUIProfile PROFILE = AndroidUIProfile.MEASURED_MULTILINE_LONG_NOTES_V4;

    public static void main(String[] args) throws Exception {
        Path directory = Path.of(args[0]);
        String revision = args[1];
        byte[] raw = Files.readAllBytes(directory.resolve("v4-" + revision + ".json"));
        if (revision.equals("1")) {
            try {
                UiPacket.decode(raw);
                throw new AssertionError("stock default admitted the private Note");
            } catch (IllegalArgumentException expected) {
                // The ordinary decoder uses the legacy horizontal profile.
            }
        }
        UiPacket frame = UiPacket.decode(raw, PROFILE);
        if (!revision.equals(frame.revision)) throw new AssertionError("incorrect frame revision");
        if (revision.equals("1")) {
            UiPacket.Node note = frame.nodes.get(FIELD);
            String original = note.text("value", "") + "Edited";
            String wrong = Normalizer.normalize(original, Normalizer.Form.NFC);
            byte[] exactPacket = frame.event(FIELD, note.generation, "textChange", original);
            byte[] wrongPacket = frame.event(FIELD, note.generation, "textChange", wrong);
            if (Arrays.equals(exactPacket, wrongPacket)) throw new AssertionError("identical control packets");
            Files.write(directory.resolve("exact-edit.json"), exactPacket);
            Files.write(directory.resolve("wrong-value.json"), wrongPacket);
        } else if (revision.equals("2")) {
            for (String action : new String[] {"entry.saveDraft", "entry.commit"}) {
                UiPacket.Node button = frame.nodes.get(action);
                Files.write(directory.resolve(action + ".json"),
                    frame.event(action, button.generation, "activate", null));
            }
        } else {
            throw new IllegalArgumentException("unsupported fixture revision");
        }
    }
}

