import Foundation
@testable @_spi(GuestUIV1) import MixerGuest
import MixerAndroid
import MixerUI
import MixerUpdates

@MainActor
private final class NoteSurface: AndroidUINativeSurface {
    let profile: AndroidUIProfile
    var capabilities: AndroidUICapabilities { profile.capabilities }
    private var owner: UUID?
    private(set) var frame: AndroidUIFrame?

    init(_ profile: AndroidUIProfile) { self.profile = profile }

    func activate(owner: UUID) throws {
        try check(self.owner == nil, "Surface already has an owner")
        self.owner = owner
    }

    func install(_ frame: AndroidUIFrame) throws {
        try check(frame.owner == owner && frame.profile == profile, "Foreign native frame")
        let packet = try object(frame.packet)
        let document = try need(packet["document"] as? [String: Any], "Native packet document")
        let root = try need(document["root"] as? [String: Any], "Native packet root")
        let children = try need(root["children"] as? [[String: Any]], "Native packet children")
        let note = try need(children.first?["properties"] as? [String: Any], "Native Note properties")
        let value = try need(note["value"] as? String, "Native Note bytes")
        let revision = frame.snapshot.document.revision
        let expected = revision == 1 ? GuestUIFieldLogNoteFixture.original : GuestUIFieldLogNoteFixture.edited
        let buttons = revision == 2 ? ["entry.saveDraft", "entry.commit"] : []
        try check(document["revision"] as? UInt64 == revision
            && note["axis"] as? String == "vertical" && value.utf8.elementsEqual(expected.utf8)
            && children.compactMap { $0["id"] as? String } == [GuestUIFieldLogNoteFixture.field] + buttons,
            "Native packet revision, vertical Note bytes or action roster")
        self.frame = frame
    }

    func revoke(owner: UUID) {
        guard self.owner == owner else { return }
        self.owner = nil
        frame = nil
    }
}

@MainActor
final class F11AndroidNote: AndroidUIPresentation {
    private static let profile = AndroidUIProfile.measuredMultilineLongNotesV4
    private let surface: NoteSurface
    private let host: AndroidUIHost
    private var reconciler: UIReconciler
    private var observer: (@MainActor (UIRenderSnapshot) -> Void)?
    private let presentSignedEdit: @MainActor (UIEventEnvelope) throws -> Void
    private var routedAction: String?
    private var dispatching = false
    private var owner: UUID?
    private(set) var snapshot: UIRenderSnapshot

    init(initial: UIDocument, presentSignedEdit: @escaping @MainActor (UIEventEnvelope) throws -> Void) throws {
        let surface = NoteSurface(Self.profile)
        self.surface = surface
