package dev.mixer.android;

import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.security.MessageDigest;
import java.util.HexFormat;
import java.util.List;

final class PacketCheck {
    private static final String FIELD = "entry.f1100000-0000-4000-8000-000000000001.note";
    private static final String ORIGINAL = "c19cbfb3593e93e8a717c23046286e5c6c178166259d2a06d2203a17e81a387d";
    private static final String EDITED = "c2df9d0971930a3b76c1471bc3de882c603f23c5d9240f6d265b4ab03e9d53d1";

    private static void require(boolean ok, String reason) {
        if (!ok) throw new AssertionError(reason);
    }

    private static void refuse(Runnable submit, String reason) {
        try {
            submit.run();
        } catch (IllegalArgumentException expected) {
            return;
        }
        throw new AssertionError(reason);
    }

    private static String hash(String text) throws Exception {
        return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256")
            .digest(text.getBytes(StandardCharsets.UTF_8)));
    }

    public static void main(String[] args) throws Exception {
        byte[] initial = Files.readAllBytes(Path.of(args[0], "v4-1.json"));
        byte[] edited = Files.readAllBytes(Path.of(args[0], "v4-2.json"));
        var v4 = AndroidUIProfile.MEASURED_MULTILINE_LONG_NOTES_V4;
        var prior = UiPacket.decode(initial, v4);
        var current = UiPacket.decode(edited, v4);
        current.requireSuccessor(prior);
        require(prior.revision.equals("1") && current.revision.equals("2"), "Unexpected frame revisions");
        var initialNote = prior.nodes.get(FIELD);
        var editedNote = current.nodes.get(FIELD);
        require(initialNote.longTextValue && editedNote.longTextValue, "V4 vertical Note policy missing");
        require(hash(initialNote.text("value", "")).equals(ORIGINAL) &&
                hash(editedNote.text("value", "")).equals(EDITED), "Unexpected Note bytes");
        require(editedNote.text("value", "").chars().filter(ch -> ch == '\n').count() == 4, "Lost line feeds");
        for (String action : List.of("entry.saveDraft", "entry.commit")) {
            var button = current.nodes.get(action);
            require(button.actions.get("activate").equals(action), "Incorrect scoped action binding");
            current.event(action, button.generation, "activate", null);
            refuse(() -> current.event(action, initialNote.generation, "activate", null), "Foreign generation accepted");
            refuse(() -> prior.event(action, button.generation, "activate", null), "Prior accepted future action");
        }
        refuse(() -> UiPacket.decode(initial, AndroidUIProfile.LEGACY_HORIZONTAL), "Legacy profile accepted vertical Note");
        System.out.println("Java V4 packet revisions 1 and 2, exact Note UTF-8, two actions, and three refusal types passed");
    }
}

