package dev.mixer.android;

import android.app.Activity;
import android.content.pm.ApplicationInfo;
import android.graphics.Bitmap;
import android.graphics.Canvas;
import android.graphics.Paint;
import android.graphics.Rect;
import android.os.Bundle;
import android.os.Handler;
import android.view.PixelCopy;
import android.view.View;
import android.view.ViewTreeObserver;
import android.widget.Button;
import android.widget.FrameLayout;
import android.widget.TextView;
import android.util.Log;
import java.io.File;
import java.io.IOException;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.Arrays;
import java.util.UUID;

public final class SignedF11Activity extends F11NativeIngress {
    private static final String TAG = "FieldLogF11Signed";

    private static final String NOTE = "entry.f1100000-0000-4000-8000-000000000001.note";
    private record Frame(long facade, long attachment, long input, long probe, UiPacket packet) {}
    private final byte[] owner = UUID.randomUUID().toString().getBytes(StandardCharsets.US_ASCII);
    private final ViewTreeObserver.OnPreDrawListener preDraw = this::beforeDraw;
    private final Handler main = new Handler(android.os.Looper.getMainLooper());
    private final Paint markerPaint = new Paint();
    private WitnessContent content;
    private AndroidUINativeSurface surface;
    private File root, packet;
    private byte[] appearance;
    private Frame current, witnessed;
    private RenderAttempt pending;
    private int frameSerial, frameAttempts;
    private static final int MARKER_SIZE = 4;
    private static final int MAX_FRAME_ATTEMPTS = 4;

    private final class RenderAttempt {
        final Frame frame;
        final View target;
        final ViewTreeObserver observer;
        final Rect localRegion;
        final Rect region;
        final FrameBufferEvidence evidence;
        final Runnable callback = () -> copyCommittedBuffer(this);
        final Runnable timeout = () -> finishAttempt(this, false);

        RenderAttempt(Frame frame, View target) {
            this.frame = frame;
            this.target = target;
            observer = content.getViewTreeObserver();
            localRegion = markerLocalRegion();
            region = markerRegion();
            evidence = new FrameBufferEvidence(++frameSerial);
        }
    }

    private final class WitnessContent extends FrameLayout {
        WitnessContent() { super(SignedF11Activity.this); }

        @Override protected void dispatchDraw(Canvas canvas) {
            super.dispatchDraw(canvas);
            RenderAttempt attempt = pending;
            if (attempt == null || !isLive(attempt) || !attempt.evidence.record(canvas.isHardwareAccelerated())) return;
            Rect marker = attempt.localRegion;
            int midpoint = marker.left + MARKER_SIZE;
            markerPaint.setColor(attempt.evidence.marker());
            canvas.drawRect(marker.left, marker.top, midpoint, marker.bottom, markerPaint);
            markerPaint.setColor(attempt.evidence.complement());
            canvas.drawRect(midpoint, marker.top, marker.right, marker.bottom, markerPaint);
        }

        @Override protected void onDetachedFromWindow() {
            clearFrameProbe();
            super.onDetachedFromWindow();
        }
    }
    private boolean resumed, registered, started, closing, enabled;
    private String lastStatus;

    @Override public void onCreate(Bundle saved) {
        super.onCreate(saved);
        requestWindowFeature(android.view.Window.FEATURE_NO_TITLE);
        if ((getApplicationInfo().flags & ApplicationInfo.FLAG_DEBUGGABLE) == 0 ||
                !getIntent().getBooleanExtra("developmentF11", false)) {
            show("Signed F11 development replay is off");
            return;
        }
        try {
            root = new File(getFilesDir(), "f11-signed");
            packet = new File(root, "offer");
            File installed = new File(root, "installed");
            for (String name : new String[]{"identity.json", "roots.json", "bridge.json", "storage.json",
                    "storage-grant.json"}) {
                installAsset("f11/installed/" + name, new File(installed, name), 131_072, true);
            }
            for (String name : new String[]{"signed-manifest.json", "assignment.json", "payload.wasm"}) {
                installAsset("f11/offer/" + name, new File(packet, name), 65_536, true);
            }
            installAsset("f11/workspace.json", new File(root, "workspace/workspace.json"), 65_536, false);
            byte[] identity = Files.readAllBytes(new File(installed, "identity.json").toPath());
            String expectedLibrary = new org.json.JSONObject(new String(identity, StandardCharsets.UTF_8))
                    .getJSONObject("engine").getString("artifact_sha256");
            try (java.util.zip.ZipFile apk = new java.util.zip.ZipFile(getApplicationInfo().sourceDir);
                    InputStream input = apk.getInputStream(apk.getEntry("lib/arm64-v8a/libAppAndroid.so"))) {
                if (!expectedLibrary.equals(sha256(input))) throw new IOException("linked owner differs");
            }
            try (InputStream input = getAssets().open("MixerAppearanceV2/descriptor.json")) {
                appearance = input.readNBytes(65_537);
            }
            if (appearance.length != 9587 || !sha256(new java.io.ByteArrayInputStream(appearance)).equals(
                    "1aeab75c457c21e5c801ab8b446490971d510021c945d0841252360becd8ead3")) {
                throw new IOException("stock appearance differs");
            }
            System.loadLibrary("AppAndroid");
            content = new WitnessContent();
            setContentView(content);
            if (!initialize()) throw new IllegalStateException("transport registration refused");
            registered = true;
            content.getViewTreeObserver().addOnPreDrawListener(preDraw);
        } catch (IOException | org.json.JSONException | RuntimeException | UnsatisfiedLinkError failure) {
            Log.e(TAG, "Open refused", failure);
            if (surface != null) surface.close();
            surface = null;
            show("Signed F11 development replay refused");
        }
    }

    private void installAsset(String asset, File destination, int limit, boolean replace) throws IOException {
        if (!replace && destination.exists()) return;
        Files.createDirectories(destination.getParentFile().toPath());
        byte[] material;
        try (InputStream input = getAssets().open(asset)) {
            material = input.readNBytes(limit + 1);
        }
        if (material.length == 0 || material.length > limit) throw new IOException("asset size rejected");
        java.nio.file.Path temp = Files.createTempFile(destination.getParentFile().toPath(), "f11-", ".tmp");
        try {
            Files.write(temp, material);
            Files.move(temp, destination.toPath(), java.nio.file.StandardCopyOption.REPLACE_EXISTING,
                    java.nio.file.StandardCopyOption.ATOMIC_MOVE);
        } finally {
            Files.deleteIfExists(temp);
        }
    }

    private static String sha256(InputStream input) throws IOException {
        try {
            MessageDigest digest = MessageDigest.getInstance("SHA-256");
            byte[] bytes = new byte[8192];
            for (int count; (count = input.read(bytes)) != -1;) digest.update(bytes, 0, count);
            StringBuilder result = new StringBuilder(64);
            for (byte value : digest.digest()) result.append(String.format(java.util.Locale.ROOT, "%02x", value & 255));
            return result.toString();
        } catch (NoSuchAlgorithmException unavailable) {
            throw new AssertionError(unavailable);
        }
    }

    private void openWhenFocused() {
        if (!registered || started || closing || !resumed || !hasWindowFocus()) return;
        started = cycle(1, 0, root.getPath(), packet.getPath(), "fieldlog-f11-android", getPackageName());
        if (started) observeStatus();
        else Log.e(TAG, "Signed owner submission refused");
    }

    private void observeStatus() {
        if (!started || closing) return;
        String state = status();
        if (!state.equals(lastStatus)) {
            Log.i(TAG, state);
            lastStatus = state;
        }
        if (!state.startsWith("Failed")) content.postDelayed(this::observeStatus, 100);
    }

    @SuppressWarnings("unused") // JNI callback, confined to the registered main Looper.
    private boolean applyGuest(long facade, long attachment, long input, long probe, byte[] bytes) {
        if (closing || !started || (current != null && current.facade() != facade)) return false;
        UiPacket admitted = UiPacket.decode(bytes, PROFILE);
        if (!admitted.root.id.equals("entry-editor") || !admitted.nodes.containsKey(NOTE) ||
                !admitted.revision.equals(current == null ? "1" : "2")) return false;
        if (current != null) admitted.requireSuccessor(current.packet());
        clearFrameProbe();
        witnessed = null;
        enabled = false;
        frameAttempts = 0;
        if (surface == null) {
            surface = new AndroidUINativeSurface(this, content, PROFILE, this::enqueue);
            surface.activate(owner);
        }
        surface.install(new AndroidUINativeSurface.Frame(owner, bytes, appearance));
        current = new Frame(facade, attachment, input, probe, admitted);
        content.invalidate();
        return true;
    }

    @SuppressWarnings("unused")
    private boolean enableGuest(long facade, boolean requested) {
        if (current == null) return !requested;
        if (current.facade() != facade) return false;
        enabled = requested;
        return true;
    }

    @SuppressWarnings("unused")
    private boolean retireGuest(long facade) {
        if (current != null && current.facade() != facade) return false;
        clearFrameProbe();
        current = witnessed = null;
        if (surface != null) { surface.close(); surface = null; }
        return true;
    }

    private void enqueue(byte[] observedOwner, byte[] envelope) {
        Frame captured = current;
        if (!Arrays.equals(owner, observedOwner) || captured == null) return;
        main.post(() -> {
            if (closing || !resumed || !hasWindowFocus() || !enabled ||
                    captured != current || captured != witnessed || surface == null || !surface.isCurrent()) return;
            int result = event(captured.facade(), captured.attachment(), captured.input(), envelope);
            Log.i(TAG, "Input revision=" + captured.packet().revision + " result=" + result);
        });
    }

    private boolean visible(View view, Frame frame) {
        return frame == current && view != null && view.isAttachedToWindow() && view.isShown() &&
                view.getGlobalVisibleRect(new Rect());
    }

    private View viewFor(Frame frame) {
        return content.findViewWithTag(NOTE);
    }

    private boolean canWitness(Frame frame) {
        return frame != null && frame == current && frame != witnessed && !closing && resumed &&
                hasWindowFocus() && surface != null && surface.isCurrent() && content.isHardwareAccelerated();
    }

    private Rect markerLocalRegion() {
        int left = (content.getWidth() - 2 * MARKER_SIZE) / 2;
        int top = (content.getHeight() - MARKER_SIZE) / 2;
        return new Rect(left, top, left + 2 * MARKER_SIZE, top + MARKER_SIZE);
    }

    private Rect markerRegion() {
        int[] xy = new int[2];
        content.getLocationInWindow(xy);
        Rect rect = markerLocalRegion();
        rect.offset(xy[0], xy[1]);
        return rect;
    }

    private boolean isLive(RenderAttempt attempt) {
        return attempt == pending && canWitness(attempt.frame) &&
                content.getViewTreeObserver() == attempt.observer && attempt.observer.isAlive() &&
                attempt.target == viewFor(attempt.frame) && visible(attempt.target, attempt.frame) &&
                attempt.region.equals(markerRegion());
    }

    private boolean beforeDraw() {
        Frame frame = current;
        if (pending != null || frameAttempts >= MAX_FRAME_ATTEMPTS || !canWitness(frame)) return true;
        View target = viewFor(frame);
        if (!visible(target, frame) || content.getWidth() < 2 * MARKER_SIZE || content.getHeight() < MARKER_SIZE)
            return true;
        RenderAttempt attempt = new RenderAttempt(frame, target);
        if (!attempt.observer.isAlive()) return true;
        pending = attempt;
        frameAttempts++;
        // ViewRootImpl collects these after pre-draw and before dispatchDraw.
        attempt.observer.registerFrameCommitCallback(attempt.callback);
        main.postDelayed(attempt.timeout, 500);
        return true;
    }

    private void copyCommittedBuffer(RenderAttempt attempt) {
        if (!isLive(attempt) || !attempt.evidence.committed()) {
            finishAttempt(attempt, false);
            return;
        }
        Bitmap bitmap = Bitmap.createBitmap(2 * MARKER_SIZE, MARKER_SIZE, Bitmap.Config.ARGB_8888);
        try {
            PixelCopy.request(getWindow(), new Rect(attempt.region), bitmap, result -> {
                try {
                    boolean copied = result == PixelCopy.SUCCESS;
                    finishAttempt(attempt, attempt.evidence.matches(copied,
                            bitmap.getPixel(1, 1), bitmap.getPixel(MARKER_SIZE + 1, 1)));
                } finally {
                    bitmap.recycle();
                }
            }, main);
        } catch (IllegalArgumentException unavailableSurface) {
            bitmap.recycle();
            finishAttempt(attempt, false);
        }
    }

    private void finishAttempt(RenderAttempt attempt, boolean bufferMatches) {
        if (attempt != pending) return;
        boolean proved = bufferMatches && isLive(attempt);
        clearFrameProbe();
        Frame frame = attempt.frame;
        if (proved && witness(frame.facade(), frame.attachment(), frame.probe(), true) == 0) {
            witnessed = frame;
            Log.i(TAG, "Committed revision=" + frame.packet().revision);
        } else if (canWitness(frame)) {
            if (frameAttempts < MAX_FRAME_ATTEMPTS) content.postInvalidateOnAnimation();
            else Log.e(TAG, "Hardware buffer unconfirmed for revision=" + frame.packet().revision);
        }
    }

    private void clearFrameProbe() {
        RenderAttempt attempt = pending;
        if (attempt == null) return;
        pending = null;
        attempt.evidence.retire();
        main.removeCallbacks(attempt.timeout);
        if (attempt.observer.isAlive()) attempt.observer.unregisterFrameCommitCallback(attempt.callback);
    }

    @Override public void onWindowFocusChanged(boolean focused) {
        super.onWindowFocusChanged(focused);
        if (!focused) clearFrameProbe();
        else {
            if (content != null) content.invalidate();
            openWhenFocused();
        }
    }

    @Override public void onResume() {
        super.onResume();
        resumed = true;
        if (surface != null) surface.onResume();
        openWhenFocused();
    }

    @Override public void onPause() {
        resumed = false;
        clearFrameProbe();
        if (surface != null) surface.onPause();
        super.onPause();
    }

    @Override public void onStop() {
        if (surface != null) surface.onStop();
        super.onStop();
    }

    @Override public void onDestroy() {
        closing = true;
        clearFrameProbe();
        if (content != null && content.getViewTreeObserver().isAlive())
            content.getViewTreeObserver().removeOnPreDrawListener(preDraw);
        if (registered && cycle(2, 0, root.getPath(), packet.getPath(), "fieldlog-f11-android", getPackageName()))
            finishRegistration(100);
        super.onDestroy();
    }

    private void finishRegistration(int attempts) {
        if (unregisterRetired()) {
            registered = false;
            if (surface != null) { surface.close(); surface = null; }
            Log.i(TAG, "Installed owner retired");
        } else if (attempts > 0) {
            new android.os.Handler(getMainLooper()).postDelayed(() -> finishRegistration(attempts - 1), 100);
        } else {
            Log.e(TAG, "Retirement unconfirmed");
        }
    }

    private void show(String text) {
        TextView label = new TextView(this);
        label.setText(text);
        setContentView(label);
    }
}

